-- Step 1: Check if there are existing workout details that reference exercises
-- This is a safety check to prevent data loss
SELECT COUNT(*) INTO @workout_count FROM workout_details;

-- Only proceed if there are no workout details
SET @can_proceed = IF(@workout_count = 0, 1, 0);

-- Display a warning message if we can't proceed
SELECT IF(@can_proceed = 0, 'WARNING: Cannot reset exercise library. There are workout details that reference exercises. Export and delete your training data first.', 'Proceeding with exercise library reset...') AS 'Status';

-- Only execute the reset if safe to do so
START TRANSACTION;

-- Step 2: If safe, delete all data from the exercise-related tables
DELETE FROM exercises WHERE @can_proceed = 1;
DELETE FROM equipment WHERE @can_proceed = 1;
DELETE FROM muscle_groups WHERE @can_proceed = 1;

-- Step 3: Reset auto-increment counters
ALTER TABLE exercises AUTO_INCREMENT = 1;
ALTER TABLE equipment AUTO_INCREMENT = 1;
ALTER TABLE muscle_groups AUTO_INCREMENT = 1;

-- Step 4: Create temporary table to hold the imported data
CREATE TEMPORARY TABLE IF NOT EXISTS temp_exercise_import (
    muscle_group VARCHAR(50),
    equipment VARCHAR(50),
    exercise_name VARCHAR(100),
    description TEXT
);

-- Step 5: Insert exercise data directly into the temporary table
-- This replaces LOAD DATA INFILE with direct INSERT statements



-- Step 6: Extract unique muscle groups and insert them
SELECT DISTINCT muscle_group FROM temp_exercise_import
WHERE @can_proceed = 1
ORDER BY muscle_group;

-- Step 7: Extract unique equipment and insert them
SELECT DISTINCT equipment FROM temp_exercise_import
WHERE @can_proceed = 1
ORDER BY equipment;

-- Step 8: Insert exercises with proper references to muscle groups and equipment
SELECT 
    t.exercise_name,
    mg.id AS muscle_group_id,
    e.id AS equipment_id,
    t.description
FROM temp_exercise_import t
JOIN muscle_groups mg ON t.muscle_group = mg.name
JOIN equipment e ON t.equipment = e.name
WHERE @can_proceed = 1;

-- Step 9: Drop temporary table
DROP TEMPORARY TABLE IF EXISTS temp_exercise_import;

-- Commit the transaction
COMMIT;

-- Display confirmation message
SELECT IF(@can_proceed = 1, 'Exercise library has been reset and populated with data.', 'Reset operation was cancelled to protect data integrity.') AS 'Result';

-- Count the number of inserted records
SELECT 
    (SELECT COUNT(*) FROM muscle_groups) AS 'Muscle Groups',
    (SELECT COUNT(*) FROM equipment) AS 'Equipment',
    (SELECT COUNT(*) FROM exercises) AS 'Exercises';
